export type IllustrationName = keyof typeof ILLUSTRATIONS;

interface IllustrationProps {
  name: IllustrationName;
  width?: number;
  height?: number;
}

export function Illustration({ name, width = 180, height = 140 }: IllustrationProps) {
  return <SvgXml xml={ILLUSTRATIONS[name]} width={width} height={height} />;
}

